{% if c.line_id %}<div class="row">💬 LINE：{{ c.line_id }}</div>{% endif %}
{% if c.address %}<div class="row">📍 {{ c.address }}</div>{% endif %}
<div>
  {% if c.category %}<span class="tag">{{ c.category }}</span>{% endif %}
  {% for k in c.keywords %}<span class="tag">{{ k }}</span>{% endfor %}
</div>
{% if c.status == 'needs_review' %}<div class="review">⚠️ AI辨識沒把握，建議人工核對：{{ c.confidence_notes }}</div>{% endif %}
