{% if c.status != 'failed' %}
  {% set bni = c.bni_status or 'unknown' %}
  {% if bni == 'bni_member' %}
  <div class="bni-badge bni-member">🔵 已是BNI會員{% if c.bni_note %}・{{ c.bni_note }}{% endif %}</div>
  {% elif bni == 'not_bni' %}
  <div class="bni-badge not-bni">🎯 非BNI會員</div>
  {% endif %}
  {% if logged_in %}
  <div class="bni-controls">
    <form method="POST" action="/card/{{ c.id }}/bni_status">
      <input type="hidden" name="bni_status" value="bni_member">
      <button type="submit" class="{{ 'active' if bni=='bni_member' else '' }}" style="color:#1f5fa8;">🔵已是會員</button>
    </form>
    <form method="POST" action="/card/{{ c.id }}/bni_status">
      <input type="hidden" name="bni_status" value="not_bni">
      <button type="submit" class="{{ 'active' if bni=='not_bni' else '' }}" style="color:#b3261e;">🎯非會員</button>
    </form>
    {% if bni != 'unknown' %}
    <form method="POST" action="/card/{{ c.id }}/bni_status">
      <input type="hidden" name="bni_status" value="unknown">
      <button type="submit">重置</button>
    </form>
    {% endif %}
  </div>
  {% endif %}
{% endif %}
<div class="actions-row">
  <a href="/card/{{ c.id }}/match">🔗 媒合</a>
  <a href="/card/{{ c.id }}/follow">📋 跟進紀錄</a>
