const former = document.querySelector('.bni-badge.bni-former');
function info(el) {
  if (!el) return null;
  const cs = getComputedStyle(el);
  return { text: el.textContent.trim().slice(0,30), color: cs.color, background: cs.backgroundColor, fontSize: cs.fontSize, fontWeight: cs.fontWeight };
}
JSON.stringify({active: info(active), former: info(former)});

